"""Generate the dispatch inventory from the registry used by the plugin."""

import argparse
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def inventory():
    rows = re.findall(
        r'^CTOOLS_COMMAND\("([^"]+)", (\w+), (\w+), (\w+)\)',
        (ROOT / "src/ctools_commands.def").read_text(),
        re.M,
    )
    assert rows, "empty command registry"
    lines = [
        "# Generated dispatch inventory",
        "",
        "Generated by `scripts/sync_architecture.py` from `src/ctools_commands.def`.",
        "Includes internal wire aliases; public ado commands are checked separately",
        "by the package and validation inventories.",
        "",
        "| Wire command | State owner | Handler | Cleanup |",
        "|---|---|---|---|",
    ]
    lines.extend("| " + " | ".join("`" + field + "`" for field in row) + " |" for row in rows)
    return "\n".join(lines) + "\n"


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    output = ROOT / "docs/COMMAND_INVENTORY.md"
    content = inventory()
    if args.check:
        if not output.exists() or output.read_text() != content:
            raise SystemExit("Stale command inventory; run scripts/sync_architecture.py")
    else:
        output.write_text(content)
    print("Command inventory checked" if args.check else "Command inventory generated")


if __name__ == "__main__":
    main()
